using System.Globalization;
using System.Text;
using Dapper;
using InovaGed.Application.Common.Database;
using InovaGed.Application.Contracts.Fiscalization;

namespace InovaGed.Infrastructure.Contracts.Fiscalization;

public sealed class ContractFiscalizationService(IDbConnectionFactory factory) : IContractFiscalizationService,IContractGlosaService,IContractFiscalizationReportService
{
 const string PeriodColumns="id,competence_month CompetenceMonth,contract_number ContractNumber,contractor_name ContractorName,contracting_unit ContractingUnit,fiscal_user_id FiscalUserId,status,total_measured_amount TotalMeasuredAmount,total_approved_amount TotalApprovedAmount,total_glossed_amount TotalGlossedAmount,total_ust TotalUst,total_items TotalItems,opened_at OpenedAt";
 const string ItemColumns="id,fiscalization_period_id FiscalizationPeriodId,productivity_entry_id ProductivityEntryId,service_catalog_id ServiceCatalogId,service_code ServiceCode,service_name ServiceName,unit,measured_quantity MeasuredQuantity,measured_ust MeasuredUst,unit_price UnitPrice,measured_amount MeasuredAmount,approved_quantity ApprovedQuantity,approved_ust ApprovedUst,approved_amount ApprovedAmount,glossed_quantity GlossedQuantity,glossed_amount GlossedAmount,status,source_type SourceType,source_id SourceId,evidence_count EvidenceCount,fiscal_notes FiscalNotes,contractor_notes ContractorNotes";
 public async Task<Guid>CreatePeriodAsync(ContractFiscalizationCreateCommand c,CancellationToken ct){await using var db=await factory.OpenAsync(ct);var id=Guid.NewGuid();try{await db.ExecuteAsync(new CommandDefinition("insert into ged.contract_fiscalization_period(id,tenant_id,competence_month,contract_number,contractor_name,contracting_unit,fiscal_user_id,manager_user_id,opened_by,notes) values(@id,@TenantId,@month,@ContractNumber,@ContractorName,@ContractingUnit,@FiscalUserId,@ManagerUserId,@OpenedBy,@Notes); insert into ged.contract_fiscalization_event(tenant_id,fiscalization_period_id,event_type,event_title,to_status,performed_by) values(@TenantId,@id,'PERIOD_CREATED','Competência de fiscalização criada','DRAFT',@OpenedBy)",new{id,c.TenantId,month=c.CompetenceMonth.ToDateTime(TimeOnly.MinValue),c.ContractNumber,c.ContractorName,c.ContractingUnit,c.FiscalUserId,c.ManagerUserId,c.OpenedBy,c.Notes},cancellationToken:ct));return id;}catch(Exception ex) when(ex.Message.Contains("ux_contract_fiscalization",StringComparison.OrdinalIgnoreCase)){throw new InvalidOperationException("Já existe fiscalização ativa para esta competência.");}}
 public async Task ImportProductivityAsync(Guid t,Guid periodId,Guid u,CancellationToken ct){await using var db=await factory.OpenAsync(ct);await using var tx=await db.BeginTransactionAsync(ct);var state=await db.QuerySingleOrDefaultAsync<(string Status,DateTime Month)>(new CommandDefinition("select status,competence_month Month from ged.contract_fiscalization_period where tenant_id=@t and id=@periodId and reg_status='A' for update",new{t,periodId},tx,cancellationToken:ct));if(state==default)throw new KeyNotFoundException();EnsureMutable(state.Status);if(await db.ExecuteScalarAsync<bool>(new CommandDefinition("select exists(select 1 from ged.contract_fiscalization_item where tenant_id=@t and fiscalization_period_id=@periodId and reg_status='A')",new{t,periodId},tx,cancellationToken:ct)))throw new InvalidOperationException("A medição já foi importada. O histórico foi preservado; inative a importação antes de reprocessar.");await db.ExecuteAsync(new CommandDefinition(@"insert into ged.contract_fiscalization_item(tenant_id,fiscalization_period_id,productivity_entry_id,service_catalog_id,service_code,service_name,unit,measured_quantity,measured_ust,unit_price,measured_amount,source_type,source_id)
select e.tenant_id,@periodId,e.id,e.service_catalog_id,s.code,s.name,coalesce(s.unit,'UST'),e.quantity,e.ust_quantity,e.unit_price,e.total_amount,e.source_type,e.source_id from ged.archive_productivity_entry e join ged.archive_service_catalog s on s.id=e.service_catalog_id where e.tenant_id=@t and e.competence_month=@month and e.reg_status='A' and e.status in('APPROVED','SUBMITTED'); update ged.contract_fiscalization_period p set status='IMPORTED',total_measured_amount=x.amount,total_approved_amount=0,total_glossed_amount=0,total_ust=x.ust,total_items=x.items from(select coalesce(sum(measured_amount),0) amount,coalesce(sum(measured_ust),0) ust,count(*) items from ged.contract_fiscalization_item where tenant_id=@t and fiscalization_period_id=@periodId and reg_status='A')x where p.tenant_id=@t and p.id=@periodId; insert into ged.contract_fiscalization_event(tenant_id,fiscalization_period_id,event_type,event_title,from_status,to_status,performed_by) values(@t,@periodId,'PRODUCTIVITY_IMPORTED','Medição de produtividade importada',@from,'IMPORTED',@u)",new{t,periodId,month=state.Month,from=state.Status,u},tx,cancellationToken:ct));await tx.CommitAsync(ct);}
 public async Task<IReadOnlyList<ContractFiscalizationPeriodItem>>ListPeriodsAsync(Guid t,ContractFiscalizationFilter f,CancellationToken ct){await using var db=await factory.OpenAsync(ct);return(await db.QueryAsync<ContractFiscalizationPeriodItem>(new CommandDefinition($"select {PeriodColumns} from ged.contract_fiscalization_period where tenant_id=@t and reg_status='A' and (@month is null or competence_month=@month) and (coalesce(@status,'')='' or status=@status) order by competence_month desc",new{t,month=f.CompetenceMonth?.ToDateTime(TimeOnly.MinValue),f.Status},cancellationToken:ct))).AsList();}
 public async Task<IReadOnlyList<ContractFiscalizationItemDto>>ListItemsAsync(Guid t,Guid p,CancellationToken ct){await using var db=await factory.OpenAsync(ct);return(await db.QueryAsync<ContractFiscalizationItemDto>(new CommandDefinition($"select {ItemColumns} from ged.contract_fiscalization_item where tenant_id=@t and fiscalization_period_id=@p and reg_status='A' order by service_name,id",new{t,p},cancellationToken:ct))).AsList();}
 public async Task<ContractFiscalizationPeriodDetails?>GetPeriodAsync(Guid t,Guid p,CancellationToken ct){await using var db=await factory.OpenAsync(ct);var period=await db.QuerySingleOrDefaultAsync<ContractFiscalizationPeriodItem>(new CommandDefinition($"select {PeriodColumns} from ged.contract_fiscalization_period where tenant_id=@t and id=@p and reg_status='A'",new{t,p},cancellationToken:ct));if(period is null)return null;var items=(await db.QueryAsync<ContractFiscalizationItemDto>(new CommandDefinition($"select {ItemColumns} from ged.contract_fiscalization_item where tenant_id=@t and fiscalization_period_id=@p and reg_status='A' order by service_name",new{t,p},cancellationToken:ct))).AsList();var glosas=(await db.QueryAsync<ContractGlosaDto>(new CommandDefinition("select g.id,g.fiscalization_item_id FiscalizationItemId,g.glosa_type GlosaType,g.reason,g.glossed_quantity GlossedQuantity,g.glossed_amount GlossedAmount,g.status,g.contractor_response ContractorResponse,g.created_at CreatedAt,g.resolution_notes ResolutionNotes from ged.contract_fiscalization_glosa g join ged.contract_fiscalization_item i on i.id=g.fiscalization_item_id where g.tenant_id=@t and i.fiscalization_period_id=@p and g.reg_status='A' order by g.created_at desc",new{t,p},cancellationToken:ct))).AsList();var evidence=(await db.QueryAsync<ContractEvidenceDto>(new CommandDefinition("select id,fiscalization_item_id FiscalizationItemId,evidence_type EvidenceType,title,description,external_url ExternalUrl,source_type SourceType,source_id SourceId,attached_at AttachedAt from ged.contract_fiscalization_evidence where tenant_id=@t and fiscalization_period_id=@p and reg_status='A' order by attached_at desc",new{t,p},cancellationToken:ct))).AsList();var events=(await db.QueryAsync<ContractEventDto>(new CommandDefinition("select event_type EventType,event_title EventTitle,event_description EventDescription,from_status FromStatus,to_status ToStatus,performed_at PerformedAt,performed_by PerformedBy from ged.contract_fiscalization_event where tenant_id=@t and fiscalization_period_id=@p and reg_status='A' order by performed_at desc",new{t,p},cancellationToken:ct))).AsList();return new(period,items,glosas,evidence,events);}
 public async Task ApproveItemAsync(Guid t,Guid id,Guid u,string?notes,CancellationToken ct){await using var db=await factory.OpenAsync(ct);var n=await db.ExecuteAsync(new CommandDefinition(@"update ged.contract_fiscalization_item i set status='APPROVED',approved_quantity=measured_quantity,approved_ust=measured_ust,approved_amount=measured_amount,glossed_quantity=0,glossed_amount=0,fiscal_notes=@notes,reviewed_by=@u,reviewed_at=now() from ged.contract_fiscalization_period p where i.id=@id and i.tenant_id=@t and p.id=i.fiscalization_period_id and p.status not in('APPROVED','CLOSED'); insert into ged.contract_fiscalization_event(tenant_id,fiscalization_period_id,fiscalization_item_id,event_type,event_title,to_status,performed_by) select @t,fiscalization_period_id,id,'ITEM_APPROVED','Item aprovado','APPROVED',@u from ged.contract_fiscalization_item where tenant_id=@t and id=@id;",new{t,id,u,notes},cancellationToken:ct));if(n==0)throw new InvalidOperationException("Item não encontrado ou competência bloqueada.");await Recalculate(t,await PeriodForItem(t,id,ct),ct);}
 public Task SubmitForApprovalAsync(Guid t,Guid p,Guid u,CancellationToken ct)=>Transition(t,p,u,"IN_REVIEW","Competência submetida para aceite","SUBMITTED",null,ct,"status in('IMPORTED','WITH_GLOSA','AWAITING_CONTRACTOR_RESPONSE')");
 public async Task ApprovePeriodAsync(Guid t,Guid p,Guid u,string?notes,CancellationToken ct){await using var db=await factory.OpenAsync(ct);var open=await db.ExecuteScalarAsync<int>(new CommandDefinition("select count(*) from ged.contract_fiscalization_glosa g join ged.contract_fiscalization_item i on i.id=g.fiscalization_item_id where g.tenant_id=@t and i.fiscalization_period_id=@p and g.reg_status='A' and g.status in('OPEN','ANSWERED')",new{t,p},cancellationToken:ct));var pending=await db.ExecuteScalarAsync<int>(new CommandDefinition("select count(*) from ged.contract_fiscalization_item where tenant_id=@t and fiscalization_period_id=@p and reg_status='A' and status='PENDING_REVIEW'",new{t,p},cancellationToken:ct));if(open>0||pending>0)throw new InvalidOperationException("Resolva todas as glosas e confira todos os itens antes do aceite.");await Transition(t,p,u,"APPROVED","Aceite mensal aprovado","APPROVED",notes,ct,"status='IN_REVIEW'",approved:true);}
 public Task RejectPeriodAsync(Guid t,Guid p,Guid u,string reason,CancellationToken ct){if(string.IsNullOrWhiteSpace(reason))throw new ArgumentException("Informe o motivo da rejeição.");return Transition(t,p,u,"REJECTED","Aceite rejeitado","REJECTED",reason,ct,"status not in('APPROVED','CLOSED')",rejected:true);}
 public Task ClosePeriodAsync(Guid t,Guid p,Guid u,CancellationToken ct)=>Transition(t,p,u,"CLOSED","Fiscalização encerrada","CLOSED",null,ct,"status='APPROVED'",closed:true);
 public async Task<Guid>CreateGlosaAsync(ContractGlosaCreateCommand c,CancellationToken ct){if(string.IsNullOrWhiteSpace(c.Reason)||(c.GlossedQuantity<=0&&c.GlossedAmount<=0))throw new ArgumentException("Toda glosa exige justificativa e quantidade ou valor maior que zero.");await using var db=await factory.OpenAsync(ct);var item=await db.QuerySingleOrDefaultAsync<(Guid PeriodId,string PeriodStatus,decimal Quantity,decimal Amount)>(new CommandDefinition("select i.fiscalization_period_id PeriodId,p.status PeriodStatus,i.measured_quantity Quantity,i.measured_amount Amount from ged.contract_fiscalization_item i join ged.contract_fiscalization_period p on p.id=i.fiscalization_period_id where i.tenant_id=@TenantId and i.id=@FiscalizationItemId and i.reg_status='A' for update",c,cancellationToken:ct));if(item==default)throw new KeyNotFoundException();EnsureMutable(item.PeriodStatus);var q=Math.Min(c.GlossedQuantity,item.Quantity);var a=Math.Min(c.GlossedAmount>0?c.GlossedAmount:(item.Quantity==0?item.Amount:item.Amount*q/item.Quantity),item.Amount);var id=Guid.NewGuid();await db.ExecuteAsync(new CommandDefinition(@"insert into ged.contract_fiscalization_glosa(id,tenant_id,fiscalization_item_id,glosa_type,reason,glossed_quantity,glossed_amount,created_by) values(@id,@TenantId,@FiscalizationItemId,@GlosaType,@Reason,@q,@a,@UserId); update ged.contract_fiscalization_item set glossed_quantity=@q,glossed_amount=@a,approved_quantity=greatest(measured_quantity-@q,0),approved_ust=case when measured_quantity=0 then 0 else measured_ust*greatest(measured_quantity-@q,0)/measured_quantity end,approved_amount=greatest(measured_amount-@a,0),status=case when @a>=measured_amount or @q>=measured_quantity then 'FULLY_GLOSSED' else 'PARTIALLY_GLOSSED' end,reviewed_by=@UserId,reviewed_at=now() where tenant_id=@TenantId and id=@FiscalizationItemId; update ged.contract_fiscalization_period set status='WITH_GLOSA' where tenant_id=@TenantId and id=@p; insert into ged.contract_fiscalization_event(tenant_id,fiscalization_period_id,fiscalization_item_id,event_type,event_title,event_description,to_status,performed_by) values(@TenantId,@p,@FiscalizationItemId,'GLOSA_CREATED','Glosa registrada',@Reason,'WITH_GLOSA',@UserId)",new{id,c.TenantId,c.FiscalizationItemId,c.GlosaType,c.Reason,q,a,c.UserId,p=item.PeriodId},cancellationToken:ct));await Recalculate(c.TenantId,item.PeriodId,ct);return id;}
 public Task RespondGlosaAsync(Guid t,Guid id,Guid u,string response,CancellationToken ct){if(string.IsNullOrWhiteSpace(response))throw new ArgumentException("Informe a manifestação da contratada.");return Resolve(t,id,u,response,"ANSWERED","GLOSA_ANSWERED","Manifestação da contratada registrada",ct,false);}
 public Task MaintainGlosaAsync(Guid t,Guid id,Guid u,string notes,CancellationToken ct)=>Resolve(t,id,u,notes,"MAINTAINED","GLOSA_MAINTAINED","Glosa mantida pelo fiscal",ct,false);
 public Task RevertGlosaAsync(Guid t,Guid id,Guid u,string notes,CancellationToken ct)=>Resolve(t,id,u,notes,"REVERTED","GLOSA_REVERTED","Glosa revertida pelo fiscal",ct,true);
 public async Task<Guid>AttachEvidenceAsync(ContractEvidenceCreateCommand c,CancellationToken ct){if(string.IsNullOrWhiteSpace(c.Title))throw new ArgumentException("Informe o título da evidência.");await using var db=await factory.OpenAsync(ct);var id=Guid.NewGuid();var n=await db.ExecuteAsync(new CommandDefinition(@"insert into ged.contract_fiscalization_evidence(id,tenant_id,fiscalization_period_id,fiscalization_item_id,evidence_type,title,description,external_url,source_type,source_id,attached_by) select @id,@TenantId,@FiscalizationPeriodId,@FiscalizationItemId,@EvidenceType,@Title,@Description,@ExternalUrl,@SourceType,@SourceId,@UserId from ged.contract_fiscalization_period where tenant_id=@TenantId and id=@FiscalizationPeriodId and status not in('APPROVED','CLOSED') and reg_status='A'; update ged.contract_fiscalization_item set evidence_count=evidence_count+1 where tenant_id=@TenantId and id=@FiscalizationItemId; insert into ged.contract_fiscalization_event(tenant_id,fiscalization_period_id,fiscalization_item_id,event_type,event_title,performed_by) select @TenantId,@FiscalizationPeriodId,@FiscalizationItemId,'EVIDENCE_ATTACHED','Evidência anexada',@UserId where exists(select 1 from ged.contract_fiscalization_evidence where id=@id)",new{id,c.TenantId,c.FiscalizationPeriodId,c.FiscalizationItemId,c.EvidenceType,c.Title,c.Description,c.ExternalUrl,c.SourceType,c.SourceId,c.UserId},cancellationToken:ct));if(n==0)throw new InvalidOperationException("Competência bloqueada ou não encontrada.");return id;}
 public async Task<ContractFiscalizationReport>GenerateSyntheticReportAsync(Guid t,Guid p,CancellationToken ct){var d=await GetPeriodAsync(t,p,ct)??throw new KeyNotFoundException();var lines=d.Items.GroupBy(x=>new{x.ServiceCode,x.ServiceName,x.Unit,x.UnitPrice}).Select((g,i)=>new ContractFiscalizationReportLine(i+1,g.Key.ServiceName,g.Key.Unit,g.Key.UnitPrice,g.Sum(x=>x.MeasuredQuantity),g.Sum(x=>x.MeasuredUst),g.Sum(x=>x.MeasuredAmount),g.Sum(x=>x.GlossedAmount),g.Sum(x=>x.ApprovedAmount),null,"SYNTHETIC",null,null,null,g.Sum(x=>x.EvidenceCount))).ToList();return new(d,lines,true);}
 public async Task<ContractFiscalizationReport>GenerateAnalyticalReportAsync(Guid t,Guid p,CancellationToken ct){var d=await GetPeriodAsync(t,p,ct)??throw new KeyNotFoundException();var lines=d.Items.Select((x,i)=>new ContractFiscalizationReportLine(i+1,x.ServiceName,x.Unit,x.UnitPrice,x.MeasuredQuantity,x.MeasuredUst,x.MeasuredAmount,x.GlossedAmount,x.ApprovedAmount,x.SourceType,x.Status,x.FiscalNotes,x.PerformedAt,x.PerformedBy,x.EvidenceCount)).ToList();return new(d,lines,false);}
 public async Task<string>ExportCsvAsync(Guid t,Guid p,string type,CancellationToken ct){var r=string.Equals(type,"synthetic",StringComparison.OrdinalIgnoreCase)?await GenerateSyntheticReportAsync(t,p,ct):await GenerateAnalyticalReportAsync(t,p,ct);var b=new StringBuilder("Numero;Servico;Natureza;Quantidade;UST;Valor medido;Valor glosado;Valor aprovado;Status\r\n");foreach(var x in r.Lines)b.AppendLine(string.Join(';',x.Number,Csv(x.Description),Csv(x.Nature),Fmt(x.Quantity),Fmt(x.Ust),Fmt(x.TotalAmount),Fmt(x.GlossedAmount),Fmt(x.ApprovedAmount),Csv(x.Status)));return b.ToString();}
 async Task Resolve(Guid t,Guid id,Guid u,string notes,string status,string eventType,string title,CancellationToken ct,bool revert){if(string.IsNullOrWhiteSpace(notes))throw new ArgumentException("Informe uma justificativa.");await using var db=await factory.OpenAsync(ct);var p=await db.ExecuteScalarAsync<Guid?>(new CommandDefinition("select i.fiscalization_period_id from ged.contract_fiscalization_glosa g join ged.contract_fiscalization_item i on i.id=g.fiscalization_item_id join ged.contract_fiscalization_period p on p.id=i.fiscalization_period_id where g.tenant_id=@t and g.id=@id and p.status not in('APPROVED','CLOSED')",new{t,id},cancellationToken:ct))??throw new InvalidOperationException("Glosa não encontrada ou competência bloqueada.");await db.ExecuteAsync(new CommandDefinition(@"update ged.contract_fiscalization_glosa set status=@status,contractor_response=case when @status='ANSWERED' then @notes else contractor_response end,responded_by=case when @status='ANSWERED' then @u else responded_by end,responded_at=case when @status='ANSWERED' then now() else responded_at end,resolved_by=case when @status in('MAINTAINED','REVERTED') then @u end,resolved_at=case when @status in('MAINTAINED','REVERTED') then now() end,resolution_notes=case when @status in('MAINTAINED','REVERTED') then @notes else resolution_notes end where tenant_id=@t and id=@id; update ged.contract_fiscalization_item i set glossed_quantity=case when @revert then 0 else i.glossed_quantity end,glossed_amount=case when @revert then 0 else i.glossed_amount end,approved_quantity=case when @revert then measured_quantity else approved_quantity end,approved_ust=case when @revert then measured_ust else approved_ust end,approved_amount=case when @revert then measured_amount else approved_amount end,status=case when @revert then 'APPROVED' when @status='ANSWERED' then 'AWAITING_CORRECTION' else status end,contractor_notes=case when @status='ANSWERED' then @notes else contractor_notes end from ged.contract_fiscalization_glosa g where g.id=@id and i.id=g.fiscalization_item_id; insert into ged.contract_fiscalization_event(tenant_id,fiscalization_period_id,event_type,event_title,event_description,performed_by) values(@t,@p,@eventType,@title,@notes,@u)",new{t,id,u,notes,status,revert,p,eventType,title},cancellationToken:ct));await Recalculate(t,p,ct);}
 async Task Transition(Guid t,Guid p,Guid u,string status,string title,string eventType,string?notes,CancellationToken ct,string guard,bool approved=false,bool rejected=false,bool closed=false){await using var db=await factory.OpenAsync(ct);var n=await db.ExecuteAsync(new CommandDefinition($@"with changed as(update ged.contract_fiscalization_period set status=@status,notes=coalesce(@notes,notes),submitted_by=case when @status='IN_REVIEW' then @u else submitted_by end,submitted_at=case when @status='IN_REVIEW' then now() else submitted_at end,approved_by=case when @approved then @u else approved_by end,approved_at=case when @approved then now() else approved_at end,rejected_by=case when @rejected then @u else rejected_by end,rejected_at=case when @rejected then now() else rejected_at end,rejection_reason=case when @rejected then @notes else rejection_reason end,closed_by=case when @closed then @u else closed_by end,closed_at=case when @closed then now() else closed_at end where tenant_id=@t and id=@p and reg_status='A' and {guard} returning 1) insert into ged.contract_fiscalization_event(tenant_id,fiscalization_period_id,event_type,event_title,to_status,event_description,performed_by) select @t,@p,@eventType,@title,@status,@notes,@u from changed",new{t,p,u,status,title,eventType,notes,approved,rejected,closed},cancellationToken:ct));if(n==0)throw new InvalidOperationException("Transição inválida ou competência bloqueada.");}
 async Task Recalculate(Guid t,Guid p,CancellationToken ct){await using var db=await factory.OpenAsync(ct);await db.ExecuteAsync(new CommandDefinition("update ged.contract_fiscalization_period p set total_measured_amount=x.measured,total_approved_amount=x.approved,total_glossed_amount=x.glossed,total_ust=x.ust,total_items=x.items from(select coalesce(sum(measured_amount),0) measured,coalesce(sum(approved_amount),0) approved,coalesce(sum(glossed_amount),0) glossed,coalesce(sum(measured_ust),0) ust,count(*) items from ged.contract_fiscalization_item where tenant_id=@t and fiscalization_period_id=@p and reg_status='A')x where p.tenant_id=@t and p.id=@p",new{t,p},cancellationToken:ct));}
 async Task<Guid>PeriodForItem(Guid t,Guid id,CancellationToken ct){await using var db=await factory.OpenAsync(ct);return await db.ExecuteScalarAsync<Guid>(new CommandDefinition("select fiscalization_period_id from ged.contract_fiscalization_item where tenant_id=@t and id=@id",new{t,id},cancellationToken:ct));}
 static void EnsureMutable(string status){if(status is "APPROVED" or "CLOSED")throw new InvalidOperationException("O aceite mensal bloqueia alterações na medição aprovada.");} static string Csv(string? x)=>$"\"{(x??"").Replace("\"","\"\"")}\"";static string Fmt(decimal x)=>x.ToString("0.0000",CultureInfo.InvariantCulture);
}
